def transform(grid):
    h, w = len(grid), len(grid[0])
    tiles = []
    for r in range(0, h, 6):
        row = []
        for c in range(0, w, 6):
            row.append(tuple(tuple(grid[r+i][c:c+5]) for i in range(5)))
        tiles.append(row)
    counts = {}
    for row in tiles:
        for tile in row:
            counts[tile] = counts.get(tile, 0) + 1
    template = max(counts, key=counts.get)
    odd = next(tile for row in tiles for tile in row if tile != template)
    return [[8 if v == 8 else (v if odd[i][j] != 8 else 1)
             for j, v in enumerate(row)] for i, row in enumerate(template)]
